pub const ArchiveIterator = struct {
    archive: *Archive,
    filter: KindEnumSet,

pub fn isErrResult(r: ArchiveResult) bool {
            return (((r == .failed) or (r == .fatal)) or (r == .warn));
    }

pub fn init(tarball_bytes: []const u8) ArchiveIteratorInitResult {
            const archive = Archive.readNew();
            if (ArchiveIterator.isErrResult(archive.readSupportFormatTar())) {
                return .{ .err = ArchiveIteratorErr{ .message = "failed to enable tar format support", .archive = archive } };
            }
            if (ArchiveIterator.isErrResult(archive.readSupportFormatGnutar())) {
                return .{ .err = ArchiveIteratorErr{ .message = "failed to enable gnutar format support", .archive = archive } };
            }
            if (ArchiveIterator.isErrResult(archive.readSupportFilterGzip())) {
                return .{ .err = ArchiveIteratorErr{ .message = "failed to enable support for gzip compression", .archive = archive } };
            }
            if (ArchiveIterator.isErrResult(archive.readSetOptions("read_concatenated_archives"))) {
                return .{ .err = ArchiveIteratorErr{ .message = "failed to set option `read_concatenated_archives`", .archive = archive } };
            }
            if (ArchiveIterator.isErrResult(archive.readOpenMemory(tarball_bytes))) {
                return .{ .err = ArchiveIteratorErr{ .message = "failed to read tarball", .archive = archive } };
            }
            return .{ .result = ArchiveIterator{ .archive = archive, .filter = KindEnumSet.initEmpty() } };
    }

pub fn next(self: *ArchiveIterator) ArchiveIteratorNextResult {
            var entry: *ArchiveEntry = undefined;
            _ = &entry;
            while (true) {
                const r = (blk: {
                break :blk archive_read_next_header(self.archive, @as([*c]*ArchiveEntry, @ptrCast(@alignCast(&(entry)))));

});
                switch (r) {
.retry => {
_ = continue;
},
.eof => {
return .{ .result = null };
},
.ok => {
const kind = bun.sys.kindFromMode(entry.filetype());
                if (self.filter.contains(kind)) {
                    continue;
                }
                return .{ .result = ArchiveIteratorNextEntry{ .entry = entry, .kind = kind } };
},
else => {
return .{ .err = ArchiveIteratorErr{ .message = "failed to read archive header", .archive = self.archive } };
},
}
            }
    }

pub fn deinit(self: *ArchiveIterator) ArchiveIteratorVoidResult {
            if (ArchiveIterator.isErrResult(self.archive.readClose())) {
                return .{ .err = ArchiveIteratorErr{ .message = "failed to close archive read", .archive = self.archive } };
            }
            if (ArchiveIterator.isErrResult(self.archive.readFree())) {
                return .{ .err = ArchiveIteratorErr{ .message = "failed to free archive read", .archive = self.archive } };
            }
            return .{ .result = .{} };
    }
    pub const NextEntry = ArchiveIteratorNextEntry;
};

